StructuredTextModel.Text:
// Read the pressure sensor

// Check if IO-Link communication is OK
IF IFM_P1_Device_Error OR IFM_P1_Communication_Error THEN
    iPressure_mBar := 0;
ELSE
    // Combine the two bytes into one 16-bit number
    wPressure := SHL(BYTE_TO_WORD(IFM_P1_Pressure_high), 8) 
                 OR BYTE_TO_WORD(IFM_P1_Pressure_low);
    
    // Convert to signed integer
    iPressure_Raw := WORD_TO_INT(wPressure);
    
    // Convert raw value to millibar (range is -1 to +10 bar = -1000 to +10000 mbar)
    // Formula: Pressure[mbar] = (INT_Value / 32767) * 10000
    iPressure_mBar := LREAL_TO_INT(INT_TO_LREAL(iPressure_Raw) / 32767.0 * 10000.0);
    
    // Make sure value is in valid range
    IF iPressure_mBar < -1000 THEN
        iPressure_mBar := -1000;
    END_IF;
    
    IF iPressure_mBar > 10000 THEN
        iPressure_mBar := 10000;
    END_IF;
	rPressure_Bar := INT_TO_LREAL(iPressure_mBar) / 1000.0;
END_IF;


// Read the flow sensor

// Check if ADC value is reasonable
IF An_Flow < 0 THEN
    rFlow_LperMin := 0.0;
    rFlow_mA := 0.0;
    
ELSIF An_Flow > 37683 THEN
    rFlow_LperMin := 1.5;
    rFlow_mA := 20.0;
    
ELSIF An_Flow > 32767 THEN
    rFlow_LperMin := 1.5;
    rFlow_mA := 20.0;
    
ELSE
    // Normal range
    
    // Convert ADC counts to milliamps
    rFlow_mA := 4.0 + (INT_TO_LREAL(An_Flow) / 8400.0) * 16.0;
    
    // Convert to liters per minute
    rFlow_LperMin := 0.05 + (INT_TO_LREAL(An_Flow) / 8400.0) * 1.45;
    
    // Keep it within sensor limits
    IF rFlow_LperMin < 0.05 THEN
        rFlow_LperMin := 0.0;
    END_IF;
    
    IF rFlow_LperMin > 1.5 THEN
        rFlow_LperMin := 1.5;
    END_IF;
    
END_IF;



IF rTotalVolume_L = 0.0 AND rPrevFlow = 0.0 THEN
    rTotalVolume_L := 0.0;
    rPrevFlow := 0.0;
END_IF;

// Sample the flow every 100ms
tmrFlowSample(IN := TRUE, PT := tSampleTime);
// Calculate total volume dispensed
// --- Reset on rising edge ---
IF bTotalReset AND NOT bTotalReset_mem THEN
    rTotalVolume_L := 0.0;
END_IF;
bTotalReset_mem := bTotalReset;

// Add up the volume
IF tmrFlowSample.Q THEN
    // Use average flow over last 100ms times the time
    rTotalVolume_L := rTotalVolume_L 
                      + ((rFlow_LperMin + rPrevFlow) / 2.0) 
                      * (100.0 / 60000.0);
    
    // Remember this flow for next time
    rPrevFlow := rFlow_LperMin;
    
    // Reset timer
    tmrFlowSample(IN := FALSE);
END_IF;
